// Self-checking time
// 45: Self-checking time (0-360 seconds)

msg.baseAddr = 45;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 45,
    quantity: 1
};
return msg;

// Advanced function bits
// 280: Multiple bit fields
//   Bit 4-7: Gen peak shaving
//   Bit 8-11: Grid peak shaving
//   Bit 12: On Grid always on
//   Bit 13: External relay
//   Bit 14: BMS error stop
//   Bit 15: DRM enable

msg.baseAddr = 280;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 1
};
return msg;

// Arc fault mode
// 283: Solar Arc Fault Mode
//   0 = close, 1 = open, 2 = clear request

msg.baseAddr = 283;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 283,
    quantity: 1
};
return msg;

// External meter settings
// 326: Phase bits (Bit1-3 = A/B/C phase)
// 327: CT ratio (200-8000)

msg.baseAddr = 326;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 326,
    quantity: 2
};
return msg;

// Parallel settings
// 417: Bit0 = enable, Bit1 = role, Bit10-15 = Modbus SN

msg.baseAddr = 417;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 417,
    quantity: 1
};
return msg;

// Build InverterAdvancedFunctionConfigState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterAdvancedFunctionConfigState: missing base address");
    return null;
}

// ---- Store partials ----

// Self-check 45
if (baseAddr === 45) {
    const selfCheckTime = data[0] || 0;
    flow.set("iafc_part_selfcheck", {
        systemSelfCheckEnabled: selfCheckTime > 0,
        selfCheckTimeSeconds: selfCheckTime
    });
}

// Advanced bits 280
else if (baseAddr === 280) {
    const bits = data[0] || 0;

    // Bit 4-7: Gen peak shaving (check if any bit set)
    const genPeakShavingEnabled = ((bits >> 4) & 0x0F) > 0;
    // Bit 8-11: Grid peak shaving
    const gridPeakShavingEnabled = ((bits >> 8) & 0x0F) > 0;
    // Bit 12: On Grid always on
    const smartLoadOnGridAlwaysOn = ((bits >> 12) & 0x01) === 1;
    // Bit 13: External relay
    const externalRelayEnabled = ((bits >> 13) & 0x01) === 1;
    // Bit 14: BMS error stop
    const bmsErrorStopEnabled = ((bits >> 14) & 0x01) === 1;
    // Bit 15: DRM enable
    const drmEnabled = ((bits >> 15) & 0x01) === 1;

    flow.set("iafc_part_adv_bits", {
        advancedFunctionWordRaw: bits,
        generatorPeakShavingEnabled: genPeakShavingEnabled,
        gridPeakShavingEnabled: gridPeakShavingEnabled,
        smartLoadOnGridAlwaysOn: smartLoadOnGridAlwaysOn,
        externalRelayEnabled: externalRelayEnabled,
        bmsErrorStopEnabled: bmsErrorStopEnabled,
        drmEnabled: drmEnabled
    });
}

// Arc fault 283
else if (baseAddr === 283) {
    const arcVal = data[0] || 0;
    flow.set("iafc_part_arc_fault", {
        arcFaultEnabled: arcVal === 1,
        arcFaultClearRequested: arcVal === 2,
        arcFaultRaw: arcVal
    });
}

// External meter 326-327
else if (baseAddr === 326) {
    const phaseBits = data[0] || 0;    // 326
    const ctRatio = data[1] || 0;      // 327

    // Decode phase bits (Bit1-3 = A/B/C)
    const phaseA = ((phaseBits >> 1) & 0x01) === 1;
    const phaseB = ((phaseBits >> 2) & 0x01) === 1;
    const phaseC = ((phaseBits >> 3) & 0x01) === 1;

    let phaseStr = "";
    if (phaseA) phaseStr += "A";
    if (phaseB) phaseStr += "B";
    if (phaseC) phaseStr += "C";
    if (!phaseStr) phaseStr = "none";

    flow.set("iafc_part_ext_meter", {
        ctRatio: ctRatio,
        phase: phaseStr,
        phaseBitsRaw: phaseBits
    });
}

// Parallel 417
else if (baseAddr === 417) {
    const parallelBits = data[0] || 0;

    // Bit 0: Enable
    const parallelEnabled = (parallelBits & 0x01) === 1;
    // Bit 1: Role (1=Master, 0=Slave)
    const isMaster = ((parallelBits >> 1) & 0x01) === 1;
    // Bit 10-15: Modbus SN (0-63)
    const modbusAddress = (parallelBits >> 10) & 0x3F;

    let role = "standalone";
    if (parallelEnabled) {
        role = isMaster ? "master" : "slave";
    }

    flow.set("iafc_part_parallel", {
        parallelEnabled: parallelEnabled,
        role: role,
        modbusAddress: modbusAddress,
        parallelBitsRaw: parallelBits
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const selfcheckPart = flow.get("iafc_part_selfcheck");
const advBitsPart = flow.get("iafc_part_adv_bits");
const arcFaultPart = flow.get("iafc_part_arc_fault");
const extMeterPart = flow.get("iafc_part_ext_meter");
const parallelPart = flow.get("iafc_part_parallel");

if (!selfcheckPart || !advBitsPart || !arcFaultPart || !extMeterPart || !parallelPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "InverterAdvancedFunctionConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    advancedFunctionWordRaw: advBitsPart.advancedFunctionWordRaw,

    arcFault: {
        enabled: arcFaultPart.arcFaultEnabled,
        clearRequested: arcFaultPart.arcFaultClearRequested
    },

    systemSelfCheckEnabled: selfcheckPart.systemSelfCheckEnabled,

    generatorPeakShavingEnabled: advBitsPart.generatorPeakShavingEnabled,
    gridPeakShavingEnabled: advBitsPart.gridPeakShavingEnabled,

    smartLoadOnGridAlwaysOn: advBitsPart.smartLoadOnGridAlwaysOn,
    externalRelayEnabled: advBitsPart.externalRelayEnabled,
    islandModeSignalEnabled: advBitsPart.externalRelayEnabled,  // Derived from relay config

    externalMeter: {
        ctRatio: extMeterPart.ctRatio,
        phase: extMeterPart.phase
    },

    bmsErrorStopEnabled: advBitsPart.bmsErrorStopEnabled,
    drmEnabled: advBitsPart.drmEnabled,

    parallel: {
        enabled: parallelPart.parallelEnabled,
        role: parallelPart.role,
        modbusAddress: parallelPart.modbusAddress
    },

    _debug: {
        selfCheckTimeSeconds: selfcheckPart.selfCheckTimeSeconds,
        arcFaultRaw: arcFaultPart.arcFaultRaw,
        phaseBitsRaw: extMeterPart.phaseBitsRaw,
        parallelBitsRaw: parallelPart.parallelBitsRaw
    }
};

// Clear partials
flow.set("iafc_part_selfcheck", null);
flow.set("iafc_part_adv_bits", null);
flow.set("iafc_part_arc_fault", null);
flow.set("iafc_part_ext_meter", null);
flow.set("iafc_part_parallel", null);

flow.set("inverterAdvancedFunctionConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
